        acquisitions: { es: "El 25% restante de CBX (Ps. 8,445.1 M, 2T26) más Ps. 19.3 M de adquisición de negocios en el 4T25 (informe del 4T25); doce meses previos: nada.", en: "The remaining 25% of CBX (Ps. 8,445.1 M, 2Q26) plus Ps. 19.3 M of business acquisition in 4Q25 (4Q25 report); prior twelve months: none." },
        dividendsPaid: { es: "Segunda exhibición de Ps. 8.42 del dividendo 2025 (Ps. 4,254.4 M, ago-2025) y Ps. 203.9 M en el 2T26. Doce meses previos: solo la primera exhibición de 2025; la distribución de 2024 fue un reembolso de capital (renglón de reembolsos).", en: "Second Ps. 8.42 installment of the 2025 dividend (Ps. 4,254.4 M, Aug-2025) and Ps. 203.9 M in 2Q26. Prior twelve months: the first 2025 installment only; 2024's distribution was a capital reduction (capital reductions row)." },
        capitalReduction: { es: "Doce meses previos: el reembolso de capital de Ps. 7,003.1 M pagado en el 2S24 en lugar de dividendo (estado de flujos de 2024).", en: "Prior twelve months: the Ps. 7,003.1 M capital reimbursement paid in 2H24 instead of a dividend (FY2024 cash-flow statement)." },
        cashFromCombination: { es: "Combinación CBX/AMP, 2T26 (informe: Ps. 5,427.1 M).", en: "CBX/AMP combination, 2Q26 (report: Ps. 5,427.1 M)." },
        bondsIssued: { es: "GAP 25-2 y 25-3 (Ps. 8,500 M, 22-ago-2025) y GAP 26 / 26-2 (Ps. 10,718 M, 31-mar-2026), según los comunicados de emisión; doce meses previos Ps. 11,648.1 M.", en: "GAP 25-2 and 25-3 (Ps. 8,500 M, 22-Aug-2025) and GAP 26 / 26-2 (Ps. 10,718 M, 31-Mar-2026), per the issuance releases; prior twelve months Ps. 11,648.1 M." },
        bondsPaid: { es: "GAP 23L (Ps. 1,120 M, 1T26; informe del 1T26); doce meses previos Ps. 7,000 M.", en: "GAP 23L (Ps. 1,120 M, 1Q26; 1Q26 report); prior twelve months Ps. 7,000 M." },
        loansPaid: { es: "Líneas bancarias: Ps. 8,026.9 M pagados y Ps. 5,359.4 M dispuestos (neto −Ps. 2,667.5 M), incl. el refinanciamiento en el 1T26 de los préstamos de Scotiabank y BBVA (US$95.5 M cada uno; informe del 1T26).", en: "Bank lines: Ps. 8,026.9 M repaid and Ps. 5,359.4 M drawn (net −Ps. 2,667.5 M), incl. the 1Q26 refinancing of the Scotiabank and BBVA loans (US$95.5 M each; 1Q26 report)." },
        interestPaid: { es: "+18.8% con deuda bruta de Ps. 65,667.3 M al 30-jun-2026 frente a Ps. 46,868.7 M un año antes (balances: préstamos bancarios y certificados).", en: "+18.8% with gross debt of Ps. 65,667.3 M at 30-Jun-2026 vs Ps. 46,868.7 M a year earlier (balance sheets: bank loans and certificados)." },
        cff: { es: "Doce meses financiados con deuda: Ps. 19,218 M de certificados emitidos y los Ps. 5,428 M de efectivo de la combinación, frente a Ps. 9,146.9 M de deuda pagada y Ps. 4,865.0 M de dividendos (incl. minoritarios).", en: "Debt-funded twelve months: Ps. 19,218 M of certificados issued and the combination's Ps. 5,428 M of cash, against Ps. 9,146.9 M of debt repaid and Ps. 4,865.0 M of dividends (incl. minorities)." },
        netChangeCash: { es: "Efectivo de Ps. 9,697.3 M (30-jun-2025) a Ps. 19,773.7 M (30-jun-2026).", en: "Cash from Ps. 9,697.3 M (30-Jun-2025) to Ps. 19,773.7 M (30-Jun-2026)." },
