        totalAssets: { es: "+Ps. 62,184.3 M: crédito mercantil e intangibles Ps. 37,703.1 M, efectivo +Ps. 10,076.4 M y +Ps. 13,721.8 M en mejoras a bienes concesionados, obras en proceso, anticipos, terreno y activo fijo (informe).", en: "+Ps. 62,184.3 M: goodwill and intangibles Ps. 37,703.1 M, cash +Ps. 10,076.4 M and +Ps. 13,721.8 M in concession improvements, construction in progress, advances, land and PP&E (report)." },
        bankLoansCurrent: { es: "Certificados con vencimiento a un año (GAP 21-V, 22L, 22 y 24-L: Ps. 7,642.5 M según sus términos), préstamos bancarios, incl. Ps. 1,305.4 M asumidos con CBX, e intereses devengados (FNAM; el informe no desglosa la línea). GAP 22L (21-sep-2026) y 21-V (9-oct-2026) se pagan a su vencimiento con las líneas bancarias de sep-2026 según el comunicado del 11-sep-2026; sin aviso de liquidación en los expedientes.", en: "Certificados maturing within a year (GAP 21-V, 22L, 22 and 24-L: Ps. 7,642.5 M by their terms), bank loans incl. Ps. 1,305.4 M assumed with CBX, and accrued interest (FNAM; the report does not itemize the line). GAP 22L (21-Sep-2026) and 21-V (9-Oct-2026) are repaid at maturity from the Sep-2026 bank facilities per the release of 11-Sep-2026; no repayment notice in the filings." },
        accountsPayable: { es: "+Ps. 1,804.6 M a/a (informe); Ps. 234.4 M llegaron con la combinación. En el trimestre las cuentas por pagar bajaron (salida de Ps. 1,906.2 M en el flujo de efectivo del 2T26).", en: "+Ps. 1,804.6 M y/y (report); Ps. 234.4 M came with the combination. In the quarter itself payables fell (Ps. 1,906.2 M outflow in the 2Q26 cash-flow statement)." },
        unearnedRevenue: { es: "Ps. 337.7 M de ingresos diferidos de CBX reconocidos en la combinación (informe).", en: "Ps. 337.7 M of CBX unearned revenue recognized in the combination (report)." },
        dividendsPayable: { es: "Los Ps. 20.80 por acción de la asamblea (22-abr-2026) declarados íntegros: Ps. 12,376.4 M (Exhibit E) = Ps. 20.80 × 595.0 M de acciones (FNAM); solo Ps. 203.9 M pagados al 30-jun. Conferencia: dos pagos, el primero «probablemente en este trimestre» (3T26) y el último en el 4T26. Jun-2025: la segunda exhibición de Ps. 8.42 del dividendo 2025, pagada en ago-2025.", en: "The AGM's Ps. 20.80 per share (22-Apr-2026) declared in full: Ps. 12,376.4 M (Exhibit E) = Ps. 20.80 × 595.0 M shares (FNAM); only Ps. 203.9 M paid by 30-Jun. Call: two payments, the first \"probably in this quarter\" (3Q26) and the last in 4Q26. Jun-2025: the second Ps. 8.42 installment of the 2025 dividend, paid Aug-2025." },
        bankLoansLT: { es: "Préstamos nuevos (informe: préstamos bancarios +Ps. 419.0 M netos, corto y largo plazo juntos). En el 1T26 se refinanciaron los préstamos de Scotiabank y BBVA (US$95.5 M cada uno) y se tomó un préstamo de Ps. 1,120 M para pagar GAP 23L (informe del 1T26).", en: "New loans (report: bank loans +Ps. 419.0 M net, current and long-term together). In 1Q26 the Scotiabank and BBVA loans (US$95.5 M each) were refinanced and a Ps. 1,120 M loan taken to repay GAP 23L (1Q26 report)." },
        bondsLT: { es: "+Ps. 11,575.5 M en esta línea; el informe cita +Ps. 18,098.0 M de certificados en total (incluida la porción circulante) = GAP 25-2 y 25-3 (Ps. 8,500 M, ago-2025) + GAP 26 y 26-2 (Ps. 10,718 M, mar-2026) − GAP 23L pagado (Ps. 1,120 M, 1T26) (FNAM, con los comunicados de emisión).", en: "+Ps. 11,575.5 M on this line; the report cites +Ps. 18,098.0 M of certificados in total (current portion included) = GAP 25-2 and 25-3 (Ps. 8,500 M, Aug-2025) + GAP 26 and 26-2 (Ps. 10,718 M, Mar-2026) − GAP 23L repaid (Ps. 1,120 M, 1Q26) (FNAM, from the issuance releases)." },
        totalLiabilities: { es: "+Ps. 27,952.3 M: certificados +Ps. 18,098.0 M, préstamos bancarios +Ps. 419.0 M netos y cuentas por pagar +Ps. 1,804.6 M (informe); dividendos por pagar +Ps. 8,122.8 M (Exhibit B).", en: "+Ps. 27,952.3 M: certificados +Ps. 18,098.0 M, bank loans +Ps. 419.0 M net and accounts payable +Ps. 1,804.6 M (report); dividends payable +Ps. 8,122.8 M (Exhibit B)." },
        commonStock: { es: "Aumento de capital de Ps. 212.1 M por las 89,740,731 acciones netas nuevas emitidas en la fusión; 595,018,195 acciones en circulación (informe, Exhibit E).", en: "Capital increase of Ps. 212.1 M for the 89,740,731 net new shares issued in the merger; 595,018,195 shares outstanding (report, Exhibit E)." },
        retainedEarnings: { es: "Exhibit E: Ps. 18,695.3 M al 1-ene-2026 − Ps. 12,376.4 M de dividendo declarado + Ps. 5,950.0 M de utilidad neta del 6M26 + Ps. 1,009.9 M de utilidades retenidas de la combinación de negocios.", en: "Exhibit E: Ps. 18,695.3 M at 1-Jan-2026 − Ps. 12,376.4 M dividend declared + Ps. 5,950.0 M of 6M26 net income + Ps. 1,009.9 M of retained earnings from the business combination." },
